113	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
114	    @Override
115	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
116	        HttpHeaders headers = new HttpHeaders();
117	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
118	        String address = normalizeAddress(owner.getAddress());
119	        if (address.isEmpty()) {
120	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
121	        }
122	        owner.setAddress(address);
123	        String telephone = toE164(owner.getTelephone());
124	        if (telephone == null) {
125	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
126	        }
127	        owner.setTelephone(telephone);
128	        if (owner.getEmail() != null) {
129	            String email = normalizeEmail(owner.getEmail());
130	            if (email == null) {
131	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
132	            }
133	            owner.setEmail(email);
134	        }
135	        LocalDate effectiveRegistrationDate = owner.getRegistrationDate();
136	        if (effectiveRegistrationDate == null) {
137	            effectiveRegistrationDate = LocalDate.now();
138	        }
139	        LocalDate registrationDate = toBusinessDay(effectiveRegistrationDate);
140	        owner.setRegistrationDate(registrationDate);
141	        if (countOwnersInCity(owner.getCity()) >= MAX_OWNERS_PER_CITY) {
142	            return new ResponseEntity<>(HttpStatus.CONFLICT);
143	        }
144	        if (countOwnersRegisteredOn(registrationDate) >= MAX_OWNERS_PER_DAY) {
145	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
146	        }
147	        // Owners sharing a household (same normalized last name and address) are given a
148	        // stable shared householdId, which forms the household component of the identityKey.
149	        String lastNameKey = householdKey(owner.getLastName());
150	        String addressKey = householdKey(owner.getAddress());
151	        List<Owner> householdMembers = new ArrayList<>();
152	        for (Owner existing : this.clinicService.findAllOwners()) {
153	            if (lastNameKey.equals(householdKey(existing.getLastName()))
154	                && addressKey.equals(householdKey(existing.getAddress()))) {
155	                householdMembers.add(existing);
156	            }
157	        }
158	        if (!householdMembers.isEmpty()) {
159	            String householdId = householdId(lastNameKey, addressKey);
160	            owner.setHouseholdId(householdId);
161	            for (Owner member : householdMembers) {
162	                if (!householdId.equals(member.getHouseholdId())) {
163	                    member.setHouseholdId(householdId);
164	                    this.clinicService.saveOwner(member);
165	                }
166	            }
167	        }
168	        // Consolidated duplicate detection: reject only when the whole identityKey
169	        // (normalized telephone | email | householdId) matches an existing owner's.
170	        String identityKey = identityKey(owner.getTelephone(), owner.getEmail(), owner.getHouseholdId());
171	        for (Owner existing : this.clinicService.findAllOwners()) {
172	            if (identityKey.equals(identityKey(toE164(existing.getTelephone()),
173	                emailForKey(existing.getEmail()), existing.getHouseholdId()))) {
174	                return new ResponseEntity<>(HttpStatus.CONFLICT);
175	            }
176	        }
177	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName()));
178	        owner.setMembershipNumber(membershipNumber(owner.getCustomerCode(), owner.getRegistrationDate()));
179	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
180	        this.clinicService.saveOwner(owner);
181	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
182	        AUDIT.info("owner created: id={} customerCode={} registrationDate={} membershipLevel={}",
183	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
184	            ownerDto.getMembershipLevel());
185	        ownerDto.setBulkSignupWarning(isBulkSignupDay());
186	        headers.setLocation(UriComponentsBuilder.newInstance()
187	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
188	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
189	    }
