284	    /**
285	     * The maximum number of owners permitted per city. Owner creation is rejected once the
286	     * owner's city already contains this many owners.
287	     */
288	    private static final int MAX_OWNERS_PER_CITY = 50;
289	
290	    /**
291	     * Counts how many existing owners live in the given city, compared case-insensitively.
292	     * This is evaluated before the new owner is persisted, so the owner being created is not
293	     * included in the count.
294	     *
295	     * @param city the new owner's city
296	     * @return the number of existing owners in that city
297	     */
298	    private int countOwnersInCity(String city) {
299	        int count = 0;
300	        for (Owner existing : this.clinicService.findAllOwners()) {
301	            if (city.equalsIgnoreCase(existing.getCity())) {
302	                count++;
303	            }
304	        }
305	        return count;
306	    }
307	
308	    /**
309	     * The maximum number of owners that may be created in a single business day. Owner
310	     * creation is rejected once this many owners already fall on the new owner's adjusted
311	     * business day {@code registrationDate}.
312	     */
313	    private static final int MAX_OWNERS_PER_DAY = 100;
314	
315	    /**
316	     * Rolls a date forward to the next business day: a Saturday or Sunday is moved forward
317	     * to the following Monday, while a weekday is returned unchanged.
318	     *
319	     * @param date the date to adjust
320	     * @return the same date if it is a weekday, otherwise the following Monday
321	     */
322	    private LocalDate toBusinessDay(LocalDate date) {
323	        DayOfWeek dayOfWeek = date.getDayOfWeek();
324	        if (dayOfWeek == DayOfWeek.SATURDAY) {
325	            return date.plusDays(2);
326	        }
327	        if (dayOfWeek == DayOfWeek.SUNDAY) {
328	            return date.plusDays(1);
329	        }
330	        return date;
331	    }
332	
333	    /**
334	     * Counts how many existing owners fall on the given business day, i.e. whose {@code
335	     * registrationDate} rolls forward to the same business day. This is evaluated before the
336	     * new owner is persisted, so the owner being created is not included in the count.
337	     *
338	     * @param businessDay the adjusted business day to count against
339	     * @return the number of existing owners registered on that business day
340	     */
341	    private int countOwnersRegisteredOn(LocalDate businessDay) {
342	        int count = 0;
343	        for (Owner existing : this.clinicService.findAllOwners()) {
344	            LocalDate existingDate = existing.getRegistrationDate();
345	            if (existingDate != null && businessDay.equals(toBusinessDay(existingDate))) {
346	                count++;
347	            }
348	        }
349	        return count;
350	    }
351	
352	    /**
353	     * The number of owners that may be created on a single business day before a bulk-signup
354	     * warning is raised. Once more than this many owners already fall on the current business
355	     * day, {@code bulkSignupWarning} is reported as {@code true} in the owner response.
356	     */
357	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
358	
359	    /**
360	     * Reports whether an unusually high number of owners have been created for today's business
361	     * day, i.e. whether more than {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners already fall on
362	     * the business day that {@code LocalDate.now()} rolls forward to.
363	     *
364	     * @return {@code true} once more than 80 owners have been created today, otherwise {@code false}
365	     */
366	    private boolean isBulkSignupDay() {
367	        return countOwnersRegisteredOn(toBusinessDay(LocalDate.now())) > BULK_SIGNUP_WARNING_THRESHOLD;
368	    }
369	
370	    /**
371	     * Builds the customer code for a newly created owner, formatted
372	     * {@code '<CITY3>-<LAST3>-<NNNN>'} where {@code CITY3} is the upper-cased first
373	     * three letters of the city, {@code LAST3} the upper-cased first three letters of
374	     * the last name and {@code NNNN} is a per-city 4-digit zero-padded sequence equal
375	     * to one more than the number of owners already in that city.
376	     *
377	     * @param city     the owner's city
378	     * @param lastName the owner's last name
379	     * @return the assigned customer code (e.g. {@code 'SYD-SMI-0007'})
380	     */
381	    private String nextCustomerCode(String city, String lastName) {
382	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase();
383	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase();
384	        int sequence = 1;
385	        for (Owner existing : this.clinicService.findAllOwners()) {
386	            if (city.equalsIgnoreCase(existing.getCity())) {
387	                sequence++;
388	            }
389	        }
390	        return String.format("%s-%s-%04d", city3, last3, sequence);
391	    }
392	
393	    /**
394	     * Builds the membership number for a newly created owner, formatted
395	     * {@code '<customerCode>-M<YY>'} where {@code customerCode} is the owner's assigned
396	     * customer code and {@code YY} is the last two digits of the owner's registration
397	     * date year, zero-padded to two digits.
398	     *
399	     * @param customerCode     the owner's assigned customer code (e.g. {@code 'SYD-SMI-0007'})
400	     * @param registrationDate the owner's registration date
401	     * @return the assigned membership number (e.g. {@code 'SYD-SMI-0007-M26'})
402	     */
403	    private String membershipNumber(String customerCode, LocalDate registrationDate) {
404	        return String.format("%s-M%02d", customerCode, registrationDate.getYear() % 100);
405	    }
406	
407	    /**
408	     * Counts how many existing owners share the given first and last name, compared
409	     * case-insensitively. This is evaluated before the new owner is persisted, so the
410	     * owner being created is not included in the count.
411	     *
412	     * @param firstName the new owner's first name
413	     * @param lastName  the new owner's last name
414	     * @return the number of existing owners with the same first and last name
415	     */
416	    private int countNamesakes(String firstName, String lastName) {
417	        int count = 0;
418	        for (Owner existing : this.clinicService.findAllOwners()) {
419	            if (firstName.equalsIgnoreCase(existing.getFirstName())
420	                && lastName.equalsIgnoreCase(existing.getLastName())) {
421	                count++;
422	            }
423	        }
424	        return count;
425	    }
426	
427	    /**
428	     * Canonical expansions applied to common street-type abbreviations during address
429	     * normalization. Keys and values are upper-cased so the lookup runs after the address
430	     * has itself been upper-cased.
431	     */
432	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
433	        "ST", "STREET",
434	        "RD", "ROAD",
435	        "AVE", "AVENUE");
436	
437	    /**
438	     * Normalizes an owner address for creation. Leading and trailing whitespace is trimmed,
439	     * every run of internal whitespace is collapsed to a single space, the result is
440	     * upper-cased and common street-type abbreviations are expanded ({@code ST -> STREET},
441	     * {@code RD -> ROAD}, {@code AVE -> AVENUE}). An abbreviation is recognized as a whole
442	     * token, optionally carrying a single trailing full stop (so both {@code 'St'} and
443	     * {@code 'St.'} become {@code 'STREET'}). The normalized value is what gets stored,
444	     * returned and compared for household duplicates; an address that is blank once
445	     * normalized fails the required-field check.
446	     *
447	     * @param address the raw address value supplied by the client
448	     * @return the normalized address (empty string when {@code address} is null or blank)
449	     */
450	    private static String normalizeAddress(String address) {
451	        if (address == null) {
452	            return "";
453	        }
454	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase();
455	        if (collapsed.isEmpty()) {
456	            return "";
457	        }
458	        StringBuilder normalized = new StringBuilder(collapsed.length());
459	        for (String token : collapsed.split(" ")) {
460	            String core = token.endsWith(".") ? token.substring(0, token.length() - 1) : token;
461	            String expanded = ADDRESS_ABBREVIATIONS.get(core);
462	            if (normalized.length() > 0) {
463	                normalized.append(' ');
464	            }
465	            normalized.append(expanded != null ? expanded : token);
466	        }
467	        return normalized.toString();
468	    }
469	
470	    /**
471	     * Normalizes a last name or address for household-duplicate comparison: leading and
472	     * trailing whitespace is trimmed, every run of internal whitespace is collapsed to a
473	     * single space and the result is lower-cased. Two owners are considered to share a
474	     * household when both their last names and addresses produce the same key.
475	     *
476	     * @param value the raw last name or address value
477	     * @return the normalized comparison key (empty string when {@code value} is null)
478	     */
479	    private static String householdKey(String value) {
480	        if (value == null) {
481	            return "";
482	        }
483	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
484	    }
485	
486	    /**
487	     * Derives the stable shared household identifier for the given normalized last name
488	     * and address keys. The identifier is deterministic — the same household (same
489	     * {@link #householdKey normalized} last name and address) always maps to the same
490	     * value — so every owner who joins a household is assigned an identical id. It is the
491	     * upper-cased first twelve hex characters of the SHA-256 digest of {@code
492	     * '<lastNameKey>|<addressKey>'}.
493	     *
494	     * @param lastNameKey the normalized last name key
495	     * @param addressKey  the normalized address key
496	     * @return the shared household identifier
497	     */
498	    private static String householdId(String lastNameKey, String addressKey) {
499	        String source = lastNameKey + "|" + addressKey;
500	        try {
501	            byte[] digest = MessageDigest.getInstance("SHA-256")
502	                .digest(source.getBytes(StandardCharsets.UTF_8));
503	            StringBuilder hex = new StringBuilder(digest.length * 2);
504	            for (byte b : digest) {
505	                hex.append(String.format("%02x", b));
506	            }
507	            return hex.substring(0, 12).toUpperCase();
508	        } catch (NoSuchAlgorithmException e) {
509	            throw new IllegalStateException("SHA-256 not available", e);
510	        }
511	    }
512	
513	    /**
514	     * Builds the derived duplicate-detection identity key from an owner's normalized
515	     * telephone, email and household id, formatted {@code
516	     * '<normalizedTelephone>|<email or empty>|<householdId or empty>'}. Two owners are
517	     * duplicates only when their whole identity keys are equal; because the telephone is
518	     * part of the key, members of the same household with different telephones produce
519	     * different keys and are both allowed.
520	     *
521	     * @param normalizedTelephone the E.164 telephone (may be {@code null})
522	     * @param email               the normalized (lower-cased) email, or {@code null} when absent
523	     * @param householdId         the shared household id, or {@code null} when the owner is not in a household
524	     * @return the identity key string
525	     */
526	    private static String identityKey(String normalizedTelephone, String email, String householdId) {
527	        return (normalizedTelephone == null ? "" : normalizedTelephone)
528	            + "|" + (email == null ? "" : email)
529	            + "|" + (householdId == null ? "" : householdId);
530	    }
531	
532	    /**
533	     * Normalizes an existing owner's stored email for identity-key comparison: trimmed and
534	     * lower-cased, mirroring {@link #normalizeEmail} without re-validating syntax. Returns
535	     * {@code null} when the owner has no email.
536	     *
537	     * @param email the existing owner's stored email (may be {@code null})
538	     * @return the trimmed, lower-cased email, or {@code null} when {@code email} is null
539	     */
540	    private static String emailForKey(String email) {
541	        return email == null ? null : email.trim().toLowerCase();
542	    }
543	
544	    /**
545	     * Normalizes a telephone number for owner creation into E.164 form. Spaces, dashes
546	     * and brackets are stripped. When the number already carries a leading {@code '+'}
547	     * and country code these are kept; a number written in national trunk form (a leading
548	     * {@code '0'}) is treated as Australian, so the {@code '0'} is dropped and country code
549	     * {@code '+61'} prepended; any other bare number is treated as a NANP number and country
550	     * code {@code '+1'} is prepended. The resulting number must have between 8 and 15 digits
551	     * after the {@code '+'}, and its national-number length must be valid for the detected
552	     * country code (see {@link #hasValidNationalLength}).
553	     *
554	     * @param telephone the raw telephone value supplied by the client
555	     * @return the E.164 telephone (e.g. {@code +61412345678}), or {@code null} when it
556	     *         cannot form a valid E.164 number (signalling a 400 Bad Request)
557	     */
558	    private static String toE164(String telephone) {
559	        if (telephone == null) {
560	            return null;
561	        }
562	        String cleaned = telephone.replaceAll("[\\s\\-()]", "");
563	        String digits;
564	        if (cleaned.startsWith("+")) {
565	            digits = cleaned.substring(1);
566	        } else if (cleaned.startsWith("0")) {
567	            digits = "61" + cleaned.substring(1);
568	        } else {
569	            digits = "1" + cleaned;
570	        }
571	        if (!digits.matches("[0-9]{8,15}")) {
572	            return null;
573	        }
574	        if (!hasValidNationalLength(digits)) {
575	            return null;
576	        }
577	        return "+" + digits;
578	    }
579	
580	    /**
581	     * Validates the national-number length of an E.164 digit string against its country
582	     * code: Australia ({@code +61}) requires exactly 9 national digits and the NANP
583	     * ({@code +1}) requires exactly 10. Numbers under any other country code are not
584	     * length-checked here — only the general 8-to-15-digit E.164 bound applies to them.
585	     *
586	     * @param digits the E.164 digits (without the leading {@code '+'})
587	     * @return {@code true} when the national-number length is valid for the country code
588	     */
589	    private static boolean hasValidNationalLength(String digits) {
590	        if (digits.startsWith("61")) {
591	            return digits.length() - 2 == 9;
592	        }
593	        if (digits.startsWith("1")) {
594	            return digits.length() - 1 == 10;
595	        }
596	        return true;
597	    }
598	
599	    /**
600	     * Normalizes an owner email for creation. A present email must be a syntactically
601	     * valid address; the returned value is lower-cased.
602	     *
603	     * @param email the raw email value supplied by the client (never {@code null} here)
604	     * @return the lower-cased email, or {@code null} when it is not a syntactically valid
605	     *         address (signalling a 400 Bad Request)
606	     */
607	    private static String normalizeEmail(String email) {
608	        String trimmed = email.trim();
609	        if (!trimmed.matches("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$")) {
610	            return null;
611	        }
612	        return trimmed.toLowerCase();
613	    }
614	}
